function ensure(s){E.ensureChildhood(s);if(!s.flow){s.flow={months:s.age*12,playing:false,speed:1,feed:[],seen:sideStories.filter(x=>x.month<s.age*12).map(x=>x.month),queue:[],activity:s.age<1?'sleep':s.age<6?'play':s.age<17?'school':'home',eventDeck:[],career:{job:s.age<6?'Дошкольница':s.age<17?'Школьница':'Занятие пока не выбрано',field:null,route:null},graduated:false,retired:false};for(const h of s.history){s.flow.feed.push({month:h.age*12,type:'choice',text:h.text,title:h.choice,scene:h.childhood?'play':'home',id:'old-'+s.flow.feed.length});}s.family.grandmother.job=s.family.grandmother.job||'бывшая библиотекарь';}return s.flow;}
function random(s){s.rng=(Math.imul(1664525,s.rng)+1013904223)>>>0;return s.rng/4294967296;}
function clamp(s){for(const k of Object.keys(s.stats))s.stats[k]=Math.max(0,Math.min(100,Math.round(s.stats[k])));}
function add(s,type,text,scene='home',title=''){const f=ensure(s),ev={month:f.months,type,text,title,scene,id:f.months+'-'+f.feed.length};f.feed.push(ev);f.activity=scene;return ev;}
function pending(s){const f=ensure(s);if(!s.started||s.ended)return null;const early=!s.childhood.finished?E.earlyScene(s):null;if(early&&early.age*12<=f.months)return {kind:'early',title:early.title,scene:early.age===2?'play':early.age===3?'family':early.age===4?'draw':early.age===5?'school':'home'};if(s.childhood.finished&&E.chapters[s.step]&&E.chapters[s.step][0]*12<=f.months)return {kind:'chapter',title:E.chapters[s.step][1],scene:s.age<17?'school':s.step===7?'park':s.step===4?'repair':s.step===6||s.step===10||s.step===13?'family':s.step===5||s.step===9?'draw':s.step===3||s.step===11?'work':'home'};const side=sideStories.find(x=>x.month<=f.months&&!f.seen.includes(x.month));return side?{kind:'side',...side}:null;}
function schedule(s,text,scene,effect={}){ensure(s).queue.push({due:s.flow.months+2,text,scene,effect});}
function careerFromChoice(s,step,i){const c=s.flow.career;if(step===2){if(i===0){c.job='Студентка';c.route='education';}else if(i===1){c.job='Помощница мастера';c.route='practice';}else{c.job='Подработка в магазине';c.route='search';}add(s,'career','Новое занятие: '+c.job+'.',i===0?'read':'work');}if(step===3&&i===0){c.job=c.field==='design'?'Дизайнер':c.field==='code'?'Программистка':'Специалист по работе с клиентами';add(s,'career','Вы приступили к работе: '+c.job.toLowerCase()+'.','work');}if(step===5&&i!==1){c.job=c.field==='code'?'Разработчица собственного проекта':'Автор небольшого проекта';add(s,'career','У вас появилось своё дело. Первые результаты ещё предстоит проверить.','work');}if(step===11){c.job=i===0?'Специалист на частичной занятости':'Пенсия и личные занятия';s.flow.retired=i!==0;add(s,'career','Ваш новый ритм: '+c.job.toLowerCase()+'.',i===0?'work':'home');}}
function resolve(s,i){const f=ensure(s),p=pending(s);if(!p)return false;const months=f.months;let o,log;if(p.kind==='early'){o=E.earlyScene(s).options[i];if(!o)return false;E.chooseEarly(s,i);log=s.last;}else if(p.kind==='chapter'){const step=s.step;o=E.chapters[step][3][i];if(!o)return false;E.choose(s,i);log=s.last;s.age=Math.floor(months/12);careerFromChoice(s,step,i);const tag=o.tag;schedule(s,tag==='learn'?'Вы вернулись к тому, чему учились, и заметили, что знакомая задача даётся легче.':tag==='create'?'Для своего занятия снова нашёлся вечер. Начатое дело не осталось только в планах.':tag==='people'?'После вашего разговора близкий человек сам вышел на связь. Общение продолжилось.':tag==='work'?'Рабочая нагрузка изменилась. Свободное время теперь приходится планировать внимательнее.':'Новый ритм понемногу становится привычным.',tag==='learn'?'read':tag==='create'?'draw':tag==='people'?'family':tag==='work'?'work':'home',tag==='learn'?{skill:1}:tag==='people'?{bond:1}:{});}else{o=p.options[i];if(!o)return false;f.seen.push(p.month);const [title,desc,trait,note]=o;if(s.age<17)s.childhood.traits[trait]++;log={age:s.age,title:p.title,choice:title,text:note,delta:{},childhood:s.age<6};s.history.push(log);s.last=log;s.memories.push({age:s.age,tag:trait==='imagination'?'create':trait==='connection'?'people':'learn',text:note});if(p.month===231){f.career.field=i===0?'code':'design';if(f.career.job==='Студентка')f.career.job=i===0?'Студентка · программирование':'Студентка · дизайн';}if(p.month===114){f.beliefs={...(f.beliefs||{}),skyLights:i===0?'likes-the-idea':i===1?'looks-for-explanations':'enjoys-the-moment'};schedule(s,i===0?'Через пару месяцев история об огнях уже стала вашей общей шуткой с Сашей. Вы сохранили рисунок выдуманного корабля.':i===1?'В местном астрономическом кружке объяснили, что цепочка огней была пролётом спутников. Вам предложили прийти посмотреть в телескоп.':'Об огнях поговорили и забыли. В памяти остался приятный вечер с Сашей.','read',i===1?{skill:1}:{});}else schedule(s,'Событие «'+p.title+'» осталось в памяти: '+note,p.scene);}
s.age=Math.floor(months/12);add(s,'choice',log.text,p.scene,log.choice);if(log.surprise)add(s,'event',log.surprise,'home');if(log.achieved)add(s,'goal','Цель выполнена: '+log.achieved,p.scene);if(log.deferred)add(s,'consequence','Планы изменились. Желание «'+log.deferred+'» осталось невыполненным.','home');clamp(s);return true;}
